    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public function state(string $code,?array $context=null):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Payment state requires a transaction.');if($context!==null&&(!in_array($context['channel']??null,['CTV','POS'],true)||!str_starts_with($code,'JC')||!is_string($context[$context['channel']==='CTV'?'partnerId':'counterId']??null)||$context[$context['channel']==='CTV'?'partnerId':'counterId']===''))throw new HttpError(409,'Ngữ cảnh thanh toán không hợp lệ.');if(str_starts_with($code,'JH')){$hotel=(new HotelPayments($this->db))->locked($code);return ['orders'=>[],'cart'=>null,'bundle'=>null,'hotel'=>$hotel,'amount'=>$hotel['total'],'locale'=>$hotel['data']['locale']??'vi'];}
        if(str_starts_with($code,'JB')){$b=$this->query('SELECT id FROM jingo_checkout_bundles WHERE code=?',[$code])->fetchColumn();if(!$b)throw new HttpError(404,'Không tìm thấy mã tổng.');$s=(new CheckoutBundles($this->db))->gatewayState($b);$d=json_decode($s['bundle']['data'],true,512,JSON_THROW_ON_ERROR);return ['orders'=>$s['orders'],'cart'=>$s['cart'],'bundle'=>$s['bundle'],'amount'=>$s['total'],'locale'=>$d['locale']??'vi'];}
        $cart=null;if(str_starts_with($code,'JC')){$cart=$this->query('SELECT * FROM jingo_carts WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart||($context===null?($cart['channel']!=='WEB'||$cart['partner_id']!==null||$cart['counter_id']!==null):($cart['channel']!==$context['channel']||$cart['partner_id']!==($context['partnerId']??null)||$cart['counter_id']!==($context['counterId']??null))))throw new HttpError(404,'Không tìm thấy giỏ thanh toán.');CheckoutLinks::guard($this->db,'cartId',$cart['id']);$rows=$this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY o.id FOR UPDATE',[$cart['id']])->fetchAll(PDO::FETCH_ASSOC);$orders=[];foreach($rows as $r)if($r['booking_status']==='CONFIRMED'&&$r['payment_status']==='UNPAID'&&!$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$r['id']])->fetchColumn())$orders[]=$r;}else{$r=$this->query('SELECT * FROM jingo_orders WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn.');if($this->query('SELECT cart_id FROM jingo_cart_orders WHERE order_id=?',[$r['id']])->fetchColumn())throw new HttpError(409,'Mở giỏ JC để thanh toán nhiều gói.');CheckoutLinks::guard($this->db,'orderId',$r['id']);$orders=[$r];}
        if(!$orders)throw new HttpError(409,'Không còn khoản chưa thanh toán.');$amount=0;foreach($orders as $r){if($r['booking_status']!=='CONFIRMED'||$r['payment_status']!=='UNPAID'||$this->query('SELECT order_id FROM jingo_order_archives WHERE order_id=?',[$r['id']])->fetchColumn()||(($context['channel']??null)==='POS'?$this->query('SELECT counter_id FROM jingo_pos_orders WHERE order_id=?',[$r['id']])->fetchColumn()!==$context['counterId']:$this->query('SELECT order_id FROM jingo_pos_orders WHERE order_id=?',[$r['id']])->fetchColumn())||(($context['channel']??null)==='CTV'?$this->query('SELECT partner_id FROM jingo_partner_orders WHERE order_id=?',[$r['id']])->fetchColumn()!==$context['partnerId']:$this->query('SELECT order_id FROM jingo_partner_orders WHERE order_id=?',[$r['id']])->fetchColumn()))throw new HttpError(409,'Chỉ thanh toán đơn web đã xác nhận, chưa thu tiền và còn hiệu lực.');$s=json_decode($r['snapshot'],true,512,JSON_THROW_ON_ERROR);if(!is_int($s['total'])||$s['total']<0)throw new HttpError(409,'Giá đơn không hợp lệ.');$amount+=$s['total'];}if($amount<1||$amount>15000000000)throw new HttpError(409,'Tổng thanh toán từ 1 đến 15 tỷ.');return ['orders'=>$orders,'cart'=>$cart,'bundle'=>null,'amount'=>$amount,'locale'=>json_decode($orders[0]['snapshot'],true,512,JSON_THROW_ON_ERROR)['locale']??'vi'];
    }
    private function authorize(array $state,array $in):void
    {
        $row=$state['bundle']?:($state['cart']?:$state['orders'][0]);$key=$in['accessKey']??null;if($key!==null){if(!hash_equals($row['access_hash'],hash('sha256',$key)))throw new HttpError(404,'Không tìm thấy đơn.');return;}if($state['bundle']||!isset($in['email']))throw new HttpError(404,'Không tìm thấy đơn.');$contact=json_decode($state['orders'][0]['contact'],true,512,JSON_THROW_ON_ERROR);if(strcasecmp(trim($contact['email']),trim($in['email']))!==0)throw new HttpError(404,'Không tìm thấy đơn.');
    }
    public function authorizeCode(array $in):void
    {
        $cart=null;$bundle=null;$orders=[];$code=$in['code'];if(str_starts_with($code,'JH')){(new HotelPayments($this->db))->authorize($code,$in);return;}if(str_starts_with($code,'JB')){$bundle=$this->query('SELECT * FROM jingo_checkout_bundles WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$bundle)throw new HttpError(404,'Không tìm thấy đơn.');}elseif(str_starts_with($code,'JC')){$cart=$this->query('SELECT * FROM jingo_carts WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$cart||$cart['channel']!=='WEB')throw new HttpError(404,'Không tìm thấy đơn.');$orders=$this->query('SELECT o.* FROM jingo_cart_orders m JOIN jingo_orders o ON o.id=m.order_id WHERE m.cart_id=? ORDER BY o.id LIMIT 1',[$cart['id']])->fetchAll(PDO::FETCH_ASSOC);if(!$orders)throw new HttpError(404,'Không tìm thấy đơn.');}else{$row=$this->query('SELECT * FROM jingo_orders WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn.');$orders=[$row];}$this->authorize(compact('bundle','cart','orders'),$in);
    }
    public static function returnPath(array $config):string{return ($config['channel']??null)==='POS'?'/quay?gateway=return':(($config['channel']??null)==='CTV'?'/ctv?gateway=return':(isset($config['hotelId'])?'/dat-phong/tra-cuu?gateway=return':'/tra-cuu?gateway=return'));}
    public static function context(array $config):?array
    {
        if(($config['channel']??'WEB')==='WEB'){if(($config['partnerId']??null)!==null||($config['counterId']??null)!==null)throw new HttpError(409,'Ngữ cảnh giỏ đã thay đổi.');return null;}
        if(($config['channel']??null)==='POS'){if(empty($config['cartId'])||!is_string($config['counterId']??null)||$config['counterId']===''||($config['partnerId']??null)!==null)throw new HttpError(409,'Ngữ cảnh quầy đã thay đổi.');return ['channel'=>'POS','counterId'=>$config['counterId']];}
        if(($config['channel']??null)!=='CTV'||empty($config['cartId'])||!is_string($config['partnerId']??null)||$config['partnerId']===''||($config['counterId']??null)!==null)throw new HttpError(409,'Ngữ cảnh giỏ đã thay đổi.');
        return ['channel'=>'CTV','partnerId'=>$config['partnerId']];
    }
    public function authorizeContext(array $in,array $context):void
    {
        if(($context['channel']??null)==='POS'){
            if(!str_starts_with($in['code'],'JC')||!is_string($context['counterId']??null)||$context['counterId']==='')throw new HttpError(404,'Không tìm thấy giỏ quầy.');$actor=$context['actor']??null;if(!is_array($actor)||!in_array($actor['role']??null,['STAFF','ADMIN'],true)||!in_array('COLLECT',$actor['permissions']??[],true))throw new HttpError(403,'Chưa được cấp quyền thu tiền.');
            if($actor['role']==='STAFF'){if(!in_array($context['counterId'],$actor['counterIds']??[],true))throw new HttpError(403,'Không được thu cho quầy này.');PosAccess::live($this->db,$actor['id'],$context['counterId'],'COLLECT');}
            if(!$this->query('SELECT id FROM jingo_counters WHERE id=? FOR UPDATE',[$context['counterId']])->fetchColumn())throw new HttpError(409,'Quầy không còn tồn tại.');$this->state($in['code'],$context);return;
        }
        if(($context['channel']??null)!=='CTV'||!is_string($context['partnerId']??null)||!str_starts_with($in['code'],'JC'))throw new HttpError(400,'Mở giỏ CTV để thanh toán online.');
        $raw=$this->query('SELECT data FROM jingo_partners WHERE id=? LOCK IN SHARE MODE',[$context['partnerId']])->fetchColumn();if(!$raw||(json_decode($raw,true,512,JSON_THROW_ON_ERROR)['status']??null)!=='ACTIVE')throw new HttpError(403,'Tài khoản CTV chưa hoạt động.');
