    public function credit(array $s,string $reference,string $provider,?string $reconciliationActor=null):void
    {
        if(!$this->db->inTransaction()||!in_array($provider,['VNPAY','SEPAY','SEPAY_CARD','PAYPAL'],true)||!str_starts_with($reference,$provider.':LIVE:'))throw new LogicException('Invalid gateway credit context.');$method=$reconciliationActor===null?$provider:'BANK';$actor=$reconciliationActor??'gateway:'.$provider;if($reconciliationActor!==null&&($provider!=='SEPAY'||$actor===''||str_starts_with($actor,'gateway:')))throw new LogicException('Invalid reconciliation actor.');if(isset($s['hotel'])){(new HotelPayments($this->db))->credit($s['hotel'],$reference,$provider,$reconciliationActor);return;}if($s['bundle']){(new CheckoutBundles($this->db))->collect(['code'=>$s['bundle']['code'],'expectedTotal'=>$s['amount'],'verified'=>true,'collectionMethod'=>$method],'gateway:'.$provider,true,$reference,$reconciliationActor);return;}if($s['cart'])$this->query("INSERT INTO jingo_payment_references(reference_hash,reference,kind,entity_id,amount) VALUES (?,?,'CART_PAYMENT',?,?)",[hash('sha256',$reference),$reference,$s['cart']['id'],$s['amount']]);$orders=new Orders($this->db);foreach($s['orders'] as $o){$ref=$s['cart']?$reference.'#'.$o['code']:$reference;$orders->act($o['id'],['requestId'=>self::uuid(),'action'=>'PAY','version'=>(int)$o['version'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total'],'method'=>'BANK','reference'=>$ref,'note'=>($reconciliationActor===null?'Tự xác nhận ':'Đối soát ').$reference],$actor,null,true);$this->query("UPDATE jingo_order_payments SET method=? WHERE order_id=? AND reference_hash=?",[$method,$o['id'],hash('sha256',$ref)]);if(!$s['cart'])OrderMail::enqueue($this->db,$o['id'],'PAY',(int)$o['version']+1);}if($s['cart']){$this->query('UPDATE jingo_carts SET version=version+1 WHERE id=?',[$s['cart']['id']]);OrderMail::enqueue($this->db,$s['orders'][0]['id'],'CART_PAY',(int)$s['orders'][0]['version']+1);}
    }
    private static function uuid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-8'.substr($h,17,3).'-'.substr($h,20);}
